<?php require 'config.php';$no=trim($_GET['application']??'');$a=null;$events=[];$error=false;if($no!==''){$s=db()->prepare("SELECT * FROM applications WHERE application_no=?");$s->execute([$no]);$a=$s->fetch();if($a){$s=db()->prepare("SELECT * FROM application_events WHERE application_id=? ORDER BY created_at ASC");$s->execute([$a['id']]);$events=$s->fetchAll();}else$error=true;}$title='Application status';require 'header.php';?>
<main class="track"><div class="intro center"><span class="kicker">APPLICATION STATUS</span><h1>Where are we with your application?</h1><p>Enter the application number you received after submitting the form.</p></div><form class="lookup"><input name="application" value="<?=e($no)?>" placeholder="PH-XXXXXXXX" required><button class="btn primary">Check status →</button></form><?php if($error):?><div class="error">Application not found. Please check the number and try again.</div><?php endif;?><?php if($a):?><section class="status-card"><div class="status-top"><div><span class="kicker"><?=e($a['application_no'])?></span><h2><?=e($a['company_name'])?></h2></div><span class="pill pill-<?=e($a['status'])?>"><?=e(str_replace('_',' ',$a['status']))?></span></div><div class="status-steps"><?php $steps=['pending','reviewing','more_info','approved'];$pos=array_search($a['status'],$steps,true);if($pos===false&&$a['status']==='declined')$pos=-1;foreach($steps as $i=>$st):?><div class="<?=($pos!==false&&$i<=$pos)?'done':''?>"><i><?=($i+1)?></i><span><?=ucwords(str_replace('_',' ',$st))?></span></div><?php endforeach;?></div><div class="status-note"><b>Latest update</b><p><?=nl2br(e($a['admin_note']?:'Your application has been received. Our team will review the information and update your status here.'))?></p></div><div class="event-history"><?php foreach($events as $ev):?><div><span>•</span><p><?=e($ev['event_text'])?><small><?=e($ev['created_at'])?></small></p></div><?php endforeach;?></div></section><?php endif;?></main><?php require 'footer.php';?>